{"action": "write", "path": "money.py", "content": """"A small, general-purpose money library.

Amounts are stored as :class:`decimal.Decimal` values so that arithmetic is
exact and free of binary floating point surprises.
"""

from decimal import Decimal, ROUND_HALF_UP

__all__ = ["Money"]


def _to_decimal(value):
    """Coerce *value* to a Decimal without introducing binary float noise."""
    if isinstance(value, Money):
        return value.amount
    if isinstance(value, Decimal):
        return value
    if isinstance(value, bool):
        return Decimal(int(value))
    if isinstance(value, int):
        return Decimal(value)
    if isinstance(value, float):
        return Decimal(repr(value))
    if isinstance(value, str):
        cleaned = value.strip().replace("$", "").replace(",", "")
        return Decimal(cleaned)
    return Decimal(str(value))


class Money:
    """An amount of money expressed in a particular currency."""

    def __init__(self, amount, currency="USD"):
        if isinstance(amount, Money):
            if currency == "USD":
                currency = amount.currency
            amount = amount.amount
        self.amount = _to_decimal(amount)
        self.currency = currency

    # ------------------------------------------------------------------
    # representation
    # ------------------------------------------------------------------
    def __repr__(self):
        return f"Money({self.amount!r}, {self.currency!r})"

    def __str__(self):
        return f"{self.currency} {self.amount:.2f}"

    # ------------------------------------------------------------------
    # equality / hashing / ordering
    # ------------------------------------------------------------------
    def __eq__(self, other):
        if isinstance(other, Money):
            return self.amount == other.amount and self.currency == other.currency
        if isinstance(other, (int, float, Decimal)) and not isinstance(other, bool):
            return self.amount == _to_decimal(other)
        return NotImplemented

    def __ne__(self, other):
        result = self.__eq__(other)
        if result is NotImplemented:
            return result
        return not result

    def __hash__(self):
        return hash((self.amount, self.currency))

    def _compare(self, other, op):
        if isinstance(other, Money):
            if other.currency != self.currency:
                raise ValueError(
                    f"cannot compare {self.currency} and {other.currency}"
                )
            return op(self.amount, other.amount)
        if isinstance(other, (int, float, Decimal)) and not isinstance(other, bool):
            return op(self.amount, _to_decimal(other))
        return NotImplemented

    def __lt__(self, other):
        return self._compare(other, lambda a, b: a < b)

    def __le__(self, other):
        return self._compare(other, lambda a, b: a <= b)

    def __gt__(self, other):
        return self._compare(other, lambda a, b: a > b)

    def __ge__(self, other):
        return self._compare(other, lambda a, b: a >= b)

    # ------------------------------------------------------------------
    # arithmetic
    # ------------------------------------------------------------------
    def _binary(self, other, op):
        if isinstance(other, Money):
            if other.currency != self.currency:
                raise ValueError(
                    f"cannot combine {self.currency} and {other.currency}"
                )
            return Money(op(self.amount, other.amount), self.currency)
        if isinstance(other, (int, float, Decimal)) and not isinstance(other, bool):
            return Money(op(self.amount, _to_decimal(other)), self.currency)
        return NotImplemented

    def __add__(self, other):
        return self._binary(other, lambda a, b: a + b)

    def __radd__(self, other):
        if other == 0:
            return self
        return self.__add__(other)

    def __sub__(self, other):
        return self._binary(other, lambda a, b: a - b)

    def __rsub__(self, other):
        if isinstance(other, (int, float, Decimal)) and not isinstance(other, bool):
            return Money(_to_decimal(other) - self.amount, self.currency)
        return NotImplemented

    def __mul__(self, other):
        if isinstance(other, (int, float, Decimal)) and not isinstance(other, bool):
            return Money(self.amount * _to_decimal(other), self.currency)
        return NotImplemented

    __rmul__ = __mul__

    def __truediv__(self, other):
        if isinstance(other, (int, float, Decimal)) and not isinstance(other, bool):
            return Money(self.amount / _to_decimal(other), self.currency)
        return NotImplemented

    def __neg__(self):
        return Money(-self.amount, self.currency)

    def __pos__(self):
        return Money(self.amount, self.currency)

    def __abs__(self):
        return Money(abs(self.amount), self.currency)

    # ------------------------------------------------------------------
    # helpers
    # ------------------------------------------------------------------
    def round(self, places=2):
        """Return a copy rounded (half up) to *places* decimal places."""
        exponent = Decimal(1).scaleb(-places)
        return Money(
            self.amount.quantize(exponent, rounding=ROUND_HALF_UP), self.currency
        )

    @property
    def cents(self):
        """The whole number of cents in this amount."""
        return int((self.amount * 100).to_integral_value(rounding=ROUND_HALF_UP))

    @classmethod
    def from_cents(cls, cents, currency="USD"):
        return cls(Decimal(cents) / 100, currency)

    def is_zero(self):
        return self.amount == 0


def money(amount, currency="USD"):
    """Convenience constructor mirroring :class:`Money`."""
    return Money(amount, currency)
